from scipy import ndimage
def comps(g, bg=8):
    res={}
    for c in sorted(set(g.flatten())-{bg}):
        m=g==c
        lab,n=ndimage.label(m,np.ones((3,3)))
        for i in range(1,n+1):
            ys,xs=np.where(lab==i)
            sub=(lab[ys.min():ys.max()+1, xs.min():xs.max()+1]==i).astype(int)
            res.setdefault(c,[]).append((len(ys),sub,(ys.min(),xs.min())))
    return res
