def comps8(g, bg):
    from scipy import ndimage
    res={}
    for col in np.unique(g):
        if col==bg: continue
        m = g==col
        lab,n = ndimage.label(m, structure=np.ones((3,3)))
        out=[]
        for i in range(1,n+1):
            sub = (lab==i)
            ys,xs = np.nonzero(sub)
            out.append((sub.sum(), sub[ys.min():ys.max()+1, xs.min():xs.max()+1].astype(int), (ys.min(),xs.min())))
        res[col]=out
    return res
